package com.gccwebos.android.portal

import java.time.Instant
import org.json.JSONObject
import org.junit.Assert.*
import org.junit.Test

class NativeSessionRecordTest {
    // Generated by the paired backend service using in-memory synthetic data; credentials normalized.
    private fun fixture() = JSONObject(javaClass.getResource("/portal/native-session-wire-synthetic.json")!!.readText())
    private val at = Instant.parse("2026-10-06T12:00:01Z")
    private fun parse(name: String = "exchange", now: Instant = at) = PortalJson.nativeSession(fixture().getJSONObject(name).toString(), now, 1000)

    @Test fun actualBackendDtosAcceptExchangeRotationAndFinalOneSecond() {
        val first = parse()
        val next = parse("refresh", Instant.parse("2026-10-06T12:31:00Z"))
        val last = parse("finalSecond", Instant.parse("2026-10-13T11:59:59Z"))
        assertEquals(first.second.issuedAt, next.second.issuedAt)
        assertEquals(first.second.expiresAt, last.second.expiresAt)
        assertEquals(1000, last.first.lifetimeMillis)
        assertNotEquals(first.second.token.value, next.second.token.value)
        val totp = fixture().getJSONObject("exchange")
        totp.getJSONObject("session").put("authMethod", "totp")
        assertNotNull(PortalJson.nativeSession(totp.toString(), at, 1000))
    }

    @Test fun malformedUnsafeAndBrowserDtosFailClosed() {
        val mutations: List<(JSONObject) -> Unit> = listOf(
            { it.put("cookie", "synthetic") },
            { it.getJSONObject("session").remove("accountId") },
            { it.getJSONObject("session").put("sessionRef", "portalbrowser_fixture") },
            { it.getJSONObject("session").put("status", "revoked") },
            { it.getJSONObject("session").put("authMethod", "cookie") },
            { it.getJSONObject("session").getJSONObject("safety").put("totpCodeReturned", true) },
            { it.getJSONObject("session").put("expiresAt", "2026-10-06T12:31:00.000Z") },
            { it.getJSONObject("refreshGrant").put("expiresAt", "2026-10-14T12:00:00.000Z") },
            { it.getJSONObject("refreshGrant").put("refreshToken", "pnr1_" + "A".repeat(42) + "B") },
            { it.getJSONObject("refreshGrant").put("refreshToken", "pnr1_" + "A".repeat(43) + "=") },
            { it.getJSONObject("refreshGrant").put("issuedAt", "2026-10-06T12:00:00Z") }
        )
        mutations.forEach { mutate ->
            val root = fixture().getJSONObject("exchange"); mutate(root)
            try { PortalJson.nativeSession(root.toString(), at, 1000); fail("Malformed native DTO accepted") }
            catch (_: IllegalArgumentException) { } catch (_: org.json.JSONException) { }
        }
    }

    @Test fun atomicVersionTwoRoundTripAndVersionOneMigrationNeverInventGrant() {
        val pair = parse()
        val saved = SavedSession.capture(pair.first, at, 1000, pair.second)
        val encoded = SessionRecordJson.encode(saved)
        val received = SessionRecordJson.decode(encoded)
        assertTrue(pair.second.sameRecord(received.refreshGrant))
        assertEquals(saved.token.value, received.token.value)
        val legacy = JSONObject(encoded).put("version", 1).apply { remove("refreshGrant") }
        val old = SessionRecordJson.decode(legacy.toString())
        assertNull(old.refreshGrant); assertNotNull(old.restore(at, 1000))
        val upgraded = SessionRecordJson.decode(SessionRecordJson.encode(old))
        assertNull(upgraded.refreshGrant)
        try { SessionRecordJson.decode(JSONObject(encoded).put("version", 1).toString()); fail() }
        catch (_: IllegalArgumentException) { }
    }

    @Test fun grantUsesAbsoluteDeadlineAndRejectsRollbackAndNoncanonicalTail() {
        val g = parse().second
        assertTrue(g.valid(at.plusSeconds(3600), 1000)) // reboot: server validation still required
        assertFalse(g.valid(at.minusSeconds(1), 1000))
        assertFalse(g.valid(at, 1000 + NativeRefreshGrant.MAX_LIFETIME_MILLIS))
        assertFalse(g.valid(g.expiresAt, 1000))
        assertFalse(g.valid(at, -1))
        assertFalse(g.toString().contains(g.token.value))
        assertFalse(SavedSession.capture(parse().first, at, 1000, g).toString().contains(g.token.value))
    }
}
